        }
        .title-box {
            background-color: white;
            border: 2px solid #333;
            padding: 15px 20px;
            text-align: center;
            width: 80%;
            margin: 0 auto 30px auto;
            font-size: 24px;
            font-weight: bold;
            line-height: 1.4;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 40px;
            text-align: left;
        }
        th, td {
            border: 1px solid white;
            padding: 15px;
            font-size: 16px;
        }
        th {
            background-color: #aeb135;
            color: white;
            font-weight: bold;
            text-align: center;
        }
        td:first-child {
            background-color: #aeb135;
            color: white;
            font-weight: bold;
            text-align: center;
            width: 120px;
        }
        td {
            background-color: #f5f7e6;
            color: #333;
        }
        .diag-cell {
            background: linear-gradient(to top right, transparent 49%, white 49%, white 51%, transparent 51%), #aeb135;
            position: relative;
            height: 60px;
            padding: 0 !important;
        }
        .diag-concept {
            position: absolute;
            top: 10px;
            right: 15px;
            color: white;
            font-weight: bold;
        }
        .diag-dimension {
            position: absolute;
            bottom: 10px;
            left: 15px;
            color: white;
            font-weight: bold;
        }
        .middle-text {
            text-align: center;
            font-size: 38px;
            font-weight: 900;
            font-style: italic;
            color: #ffffe0;
            text-shadow: 
                -2px -2px 0 #000,  
                 2px -2px 0 #000,
                -2px  2px 0 #000,
                 2px  2px 0 #000,
                 3px  3px 5px rgba(0,0,0,0.5);
            margin: 40px 0;
            line-height: 1.3;
            letter-spacing: 2px;
        }
        .diagram-container {
            position: relative;
            width: 100%;
            height: 400px;
            margin: 30px auto;
        }
        .diag-block {
            position: absolute;
            height: 70px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            color: white;
            font-weight: bold;
            font-size: 18px;
            box-sizing: border-box;
        }
        .diag-block span {
            font-size: 14px;
            font-weight: normal;
            margin-top: 5px;
        }
        .block-blue {
            background-color: #2b7eb3;
            left: 5%;
            bottom: 10%;
            width: 45%;
            z-index: 1;
        }
        .block-yellow {
            background-color: #ffb612;
            left: 32%;
            bottom: 35%;
            width: 45%;
            z-index: 2;
        }
        .block-green {
            background-color: #aeb135;
            left: 59%;
            bottom: 60%;
            width: 35%;
            z-index: 3;
        }
        .block-green::after {
            content: '';
            position: absolute;
            right: -35px;
            top: 0;
            border-top: 35px solid transparent;
            border-bottom: 35px solid transparent;
            border-left: 35px solid #aeb135;
        }
        .white-box {
            position: absolute;
            background-color: white;
            padding: 12px 15px;
            font-size: 16px;
            color: #333;
            z-index: 4;
            box-shadow: 1px 1px 5px rgba(0,0,0,0.1);
            line-height: 1.4;
        }
        .wb-1 {
            left: 5%;
            bottom: calc(10% + 70px);
            width: 22%;
        }
        .wb-2 {
            left: 32%;
            bottom: calc(35% + 70px);
            width: 22%;
        }
        .wb-3 {
            left: 59%;
            bottom: calc(60% + 70px);
            width: 22%;
        }
        .footer {
            text-align: right;
            font-size: 14px;
            color: #666;
            margin-top: 20px;
            padding-right: 20px;
        }
    </style>
</head>
<body>
    <div class="container">
